CREATE TRIGGER RefCusRateCodeLanguage_Combined
	ON RefCusRateCodeLanguage
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZXC_DataSetPK = ZY1_ZZR_RateType,
		ZXC_DataSetCode = 'ZZR'
		FROM RefCusRateCodeLanguage t
		JOIN inserted ON t.ZXC_PK = inserted.ZXC_PK
		LEFT JOIN RefCusRateCode ON inserted.ZXC_ZY1_RateCode = ZY1_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZXC_DataSetPK, t.ZXC_DataSetCode
	FROM RefCusRateCodeLanguage t
	JOIN inserted ON t.ZXC_PK = inserted.ZXC_PK
	UNION
	SELECT ZXC_DataSetPK, ZXC_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusRateCodeLanguage_DataProcessingResult_Delete
	ON RefCusRateCodeLanguage
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZXC_PK
	END
GO
